SELECT json_query(http_request('https://jsonplaceholder.typicode.com/posts/1', 'GeT', '', '{}', 30000, TRUE, '', ''), json_query(CAST('$.status' AS JSON), '$.a')) AS `status`;
SELECT json_query(http_request('https://jsonplaceholder.typicode.com/posts/1', 'GeT', '', '{}', 30000, TRUE, '', ''), 'DELETE') AS `status`;